function rotate(arr, k){
  k = k % arr.length; // it will make sure k should be between n to n-1

  function reverse(a, left, right) {
    while( left < right) {
      let temp = a[left]
      a[left] = a[right];
      a[right] = temp;
      left++;
      right--;
    }
  }
//nums = [1,2,3,4,5,6,7]
//k = 3
//Reverse all → [7,6,5,4,3,2,1]
//Reverse first 3 → [5,6,7,4,3,2,1]
//Reverse rest → [5,6,7,1,2,3,4]
  reverse(arr, 0, arr.length - 1);
  reverse(arr, 0, k-1);
  reverse(arr, k, arr.length-1)
  return arr;
}

  console.log(rotate([1,2,3,4,5,6], 7))
